// Cache TTL: "1h" enables Anthropic's extended cache (extended-cache-ttl-2025-04-11
// beta). "off" reverts to default 5-min ephemeral. Cuts CACHE-BREAK floods on
// idle conversations.
const CACHE_TTL = (process.env.BRIDGE_CACHE_TTL || "1h").toLowerCase();
const EXTENDED_CACHE = CACHE_TTL === "1h";
const EPHEMERAL = EXTENDED_CACHE
  ? { type: "ephemeral", ttl: "1h" }
  : { type: "ephemeral" };

// Cache-diagnosis beta. When enabled, Anthropic returns a `diagnostics` field
// on the response telling us *why* a cache miss happened (system_changed,
// tools_changed, messages_changed, model_changed, ...). Default ON — cheap
// observability win; set BRIDGE_CACHE_DIAGNOSIS=off to disable.
const CACHE_DIAGNOSIS = (process.env.BRIDGE_CACHE_DIAGNOSIS || "on").toLowerCase() !== "off";

// Thinking-block clearing (mirrors Claude Code v2.1.168). When ON (default) and
// the request carries thinking blocks, the bridge attaches the
// context-management-2025-06-27 beta + a clear_thinking_20251015 edit so
// Anthropic clears stale thinking from completed turns server-side. On long
// opus-4.5+/sonnet-4.6+ goal sessions, accumulated thinking signatures alone are
// ~50% of the wire payload (measured: 81,983/163,307 tok on a real burst dump);
// clearing cuts the billed + context cost without any client-side surgery on the
// signed blocks (which would risk the 400 "latest assistant message cannot be
// modified" guard). The beta + edit shape is copied verbatim from Claude Code's
// own handler. Set BRIDGE_CLEAR_THINKING=off to disable.
const CLEAR_THINKING = (process.env.BRIDGE_CLEAR_THINKING || "on").toLowerCase() !== "off";
const CLEAR_THINKING_BETA = "context-management-2025-06-27";

// Prompt fingerprinting: hash the cacheable prefix (system + tools) and the
// named sub-blocks pi injects, so /cache-divergence can spot two sessions in
// the same cwd whose system anchor has split byte-for-byte (the usual cause of
// a fresh session reading 0% from a warm sibling). Pure observability — never
// mutates the upstream request, so it has no cache impact of its own. Set
// BRIDGE_FINGERPRINT=off to disable.
const FINGERPRINT = (process.env.BRIDGE_FINGERPRINT || "on").toLowerCase() !== "off";

// Named sub-blocks to hash individually, by their delimiting tags. In OAuth
// mode pi's real system prompt is moved to messages[0] as <system-context>, so
// these tags live there, not in params.system.
const FINGERPRINT_SECTIONS = [
  { name: "persistentMemory", open: "<persistent-memory>", close: "</persistent-memory>" },
  { name: "projectContext",   open: "<project_context>",   close: "</project_context>" },
  { name: "skills",           open: "<available_skills>",  close: "</available_skills>" },
];

