// Group same-cwd callers and flag where their prompt fingerprints disagree.
// A field that holds >1 distinct non-null hash across siblings = anchor split:
// those sessions can't share that cached block, so cross-session reads miss.
function cacheDivergenceSnapshot(windowMs = CALLER_WINDOWS["1h"]) {
  const fields = ["system", "tools", "persistentMemory", "projectContext", "skills"];
  const byCwd = new Map();
  for (const caller of summarizeCallers(windowMs)) {
    const fp = caller.meta?.fingerprint;
    if (!fp) continue;
    const cwd = caller.meta?.cwd || "(no-cwd)";
    if (!byCwd.has(cwd)) byCwd.set(cwd, []);
    byCwd.get(cwd).push({
      id: caller.id,
      title: caller.meta?.title,
      pid: caller.meta?.pid,
      piSessionId: caller.meta?.piSessionId,
      childAgent: caller.meta?.childAgent,
      cacheWrite: caller.cacheWrite,
      cacheRead: caller.cacheRead,
      fingerprint: fp,
    });
  }

  const groups = [];
  for (const [cwd, callers] of byCwd) {
    const diverged = fields.filter((f) => {
      const vals = new Set(callers.map((c) => c.fingerprint?.[f]).filter(Boolean));
      return vals.size > 1;
    });
    groups.push({ cwd, callerCount: callers.length, diverged, callers });
  }
  // Diverging, busiest cwds first.
  groups.sort((a, b) => (b.diverged.length - a.diverged.length) || (b.callerCount - a.callerCount));
  return { window: "1h", groups };
}

function handleCacheDivergence(_req, res) {
  res.writeHead(200, { "Content-Type": "application/json" });
  res.end(
    JSON.stringify({
      startedAt: new Date(stats.startTime).toISOString(),
      fingerprinting: FINGERPRINT,
      ...cacheDivergenceSnapshot(),
    })
  );
}

function handleNotFound(_req, res) {
  res.writeHead(404, { "Content-Type": "application/json" });
  res.end(JSON.stringify({ error: "Not found" }));
}

// --- Server ---
const server = http.createServer((req, res) => {
  const url = new URL(req.url, `http://${req.headers.host}`);
  const path = url.pathname;

  // Support /source/<name>/v1/messages for caller identification.
  // The prefix is stripped; <name> becomes the bridge.source span attribute.
  const sourceMatch = path.match(/^\/source\/([^/]+)(\/.*)/)
  const routePath   = sourceMatch ? sourceMatch[2] : path;
  const pathSource  = sourceMatch ? sourceMatch[1] : undefined;

  if (routePath === "/v1/messages" && req.method === "POST") {
    handleMessages(req, res, pathSource);
  } else if (routePath === "/health" && req.method === "GET") {
    handleHealth(req, res);
  } else if (routePath === "/status" && req.method === "GET") {
    handleStatus(req, res);
  } else if (routePath === "/top-callers" && req.method === "GET") {
    handleTopCallers(req, res);
  } else if (routePath === "/cache-divergence" && req.method === "GET") {
    handleCacheDivergence(req, res);
  } else {
    handleNotFound(req, res);
  }
});

// --- Graceful Shutdown ---
function shutdown(signal) {
  console.log(`\n[${signal}] Shutting down...`);
  server.close(() => {
    console.log("Server closed.");
    process.exit(0);
  });
  // Force exit after 5s if connections don't close
  setTimeout(() => process.exit(1), 5000);

