// Prefix a tool name for the OAuth wire format unless it is a Claude Code tool,
// an Anthropic native tool, or already prefixed (idempotent).
function prefixToolName(name) {
  if (
    typeof name !== "string" ||
    CLAUDE_CODE_TOOLS.has(name) ||
    ANTHROPIC_NATIVE_TOOLS.has(name) ||
    name.startsWith("mcp__")
  ) {
