// Scan message content for tool_reference blocks and prefix their names using
// the same guard as the tools[] map. tool_reference is request-only content
// (no response-side change needed). Mutates blocks in place; returns messages.
//
// On the wire (pi-ai anthropic.ts convertContentBlocks) a tool_reference block
// is `{ type: "tool_reference", tool_name }` and is NESTED inside a
// `tool_result` block's `content[]` (a user message -> tool_result ->
// tool_reference). It can also appear directly in a message's content[]. We
// recurse over every nested `content` array and prefix whichever name field is
// present (`tool_name` on the wire; `name` defensively). The mcp__ guard keeps
// it idempotent across replays of already-prefixed history.
function rewriteToolReferenceBlocks(blocks) {
  if (!Array.isArray(blocks)) return;
  for (const block of blocks) {
    if (!block || typeof block !== "object") continue;
    if (block.type === "tool_reference") {
      if (typeof block.tool_name === "string") block.tool_name = prefixToolName(block.tool_name);
      if (typeof block.name === "string") block.name = prefixToolName(block.name);
    }
    if (Array.isArray(block.content)) rewriteToolReferenceBlocks(block.content);
  }
}

function rewriteToolReferenceNames(messages) {
  if (!Array.isArray(messages)) return messages;
  for (const msg of messages) {
    if (msg && Array.isArray(msg.content)) rewriteToolReferenceBlocks(msg.content);
